from scipy.optimize import least_squares
def mk(fam):
    def model(p):
        if fam=='voce_kT':
            # sigma = (a+bT+cT2) + (d+eT+fT2)*(1-exp(-(k0+k1 T) eps))
            a,b,c,d,e,f,k0,k1=p
            return (a+b*T+c*T**2)+(d+e*T+f*T**2)*(1-np.exp(-(k0+k1*T)*eps))
        if fam=='voce_kT_pow':
            a,b,c,d,e,f,k0,k1,n=p
            return (a+b*T+c*T**2)+(d+e*T+f*T**2)*(1-np.exp(-(k0+k1*T)*eps**n))
        if fam=='pow_T':
            a,b,c,d,e,f,n0,n1=p
            return (a+b*T+c*T**2)+(d+e*T+f*T**2)*eps**(n0+n1*T)
        if fam=='pow_exp':
            a,b,c,d,e,f,n0,n1,k=p
            return (a+b*T+c*T**2)+(d+e*T+f*T**2)*eps**(n0+n1*T)*np.exp(-k*eps)
    return model
